Lemma carve_nth_other : forall ws total auser size (i : nat) (k : nat),
  Z.of_nat i <= total -> (Z.of_nat k < total - Z.of_nat i \/ total <= Z.of_nat k) ->
  nth_error (carve ws total auser size i) k = nth_error ws k.
